-- Condicionales y causales (plan de fusión, Luciano et al., 2009): transformación como última fase.
-- Vincular Mutuamente: usar la regla para conseguir algo («Si Pim bebe, Tok baila. Quieres ver a Tok
-- bailar. ¿Qué tiene que hacer Pim?»), B → A. Redes causales: «Quieres que al final pase esto: … ¿Qué
-- tiene que pasar primero de todo?», C → A. «Seguir Reglas Condicionales» no se toca (pendiente de
-- valorar y de la revisión pliance/tracking).
begin;
update clases_rft_base c set consignas = $j${"test_mutuo:B→A": "Si Pim bebe, Tok baila. ¿Cuándo baila Tok?", "entrenamiento:A→B": "Si Pim bebe, Tok baila. ¿Qué hace Tok si Pim bebe?", "transformacion_funciones:B→A": "Si Pim bebe, Tok baila. Quieres ver a Tok bailar. ¿Qué tiene que hacer Pim?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Condicionales' and c.nombre = 'Clase 1';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:B→A', $j$Si Pim bebe, Tok baila. Quieres ver a Tok bailar. ¿Qué tiene que hacer Pim?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Condicionales' and c.nombre = 'Clase 1';
