update programas_base set secuencia_rft = '[{"fase": "entrenamiento", "origen": "A", "destino": "B"}, {"fase": "test_mutuo", "origen": "B", "destino": "A"}, {"fase": "transformacion_funciones", "origen": "B", "destino": "A"}]'::jsonb,
  objetivo = objetivo || $t$ Además, usa la regla para conseguir algo («Quieres ver a Tok bailar. ¿Qué tiene que hacer Pim?» → bebe).$t$,
  instrucciones_terapeuta = regexp_replace(regexp_replace(instrucciones_terapeuta, E'\n(Generalización \\(sondas\\):)', $t$
Fase 3 - Test de Transformación de Funciones a través de la regla, sin entrenamiento directo (Luciano et al., 2009):

1. Enuncie la regla y plantee un deseo sobre el consecuente: "Si Pim bebe, Tok baila. Quieres ver a Tok bailar. ¿Qué tiene que hacer Pim?" (respuesta: bebe). La función del consecuente (algo que se quiere) pasa a la condición a través de la regla: el alumno usa la regla para conseguirlo.
2. No refuerce diferencialmente durante estos ensayos, pero registre la respuesta.
3. Elegir el consecuente indica que repite lo que ha oído al final de la pregunta en lugar de usar la regla.

\1$t$), E'(- Test de vínculo mutuo:[^\n]*\n)', $t$\1- Transformación de funciones: B → A ("Quieres ver a Tok bailar. ¿Qué tiene que hacer Pim?"; la respuesta es A)
$t$)
where clinica_id is null and nombre = 'Vincular Mutuamente Relaciones Condicionales' and instrucciones_terapeuta not like '%Fase 3 - Test de Transformación de Funciones a través de la regla%';
update programas_alumno pa set objetivo = pb.objetivo, secuencia_rft = pb.secuencia_rft, instrucciones_terapeuta = pb.instrucciones_terapeuta
from programas_base pb where pa.programa_base_id = pb.id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Condicionales';

update programas_base set secuencia_rft = '[{"fase": "entrenamiento", "origen": "A", "destino": "B"}, {"fase": "entrenamiento", "origen": "B", "destino": "C"}, {"fase": "test_mutuo", "origen": "B", "destino": "A"}, {"fase": "test_mutuo", "origen": "C", "destino": "B"}, {"fase": "test_combinatorio", "origen": "A", "destino": "C"}, {"fase": "test_combinatorio", "origen": "C", "destino": "A"}, {"fase": "transformacion_funciones", "origen": "C", "destino": "A"}]'::jsonb,
  objetivo = objetivo || $t$ Además, usa la red para conseguir un efecto final («Quieres que al final pase esto… ¿Qué tiene que pasar primero de todo?»).$t$,
  instrucciones_terapeuta = regexp_replace(regexp_replace(instrucciones_terapeuta, E'\n(Generalización \\(sondas\\):)', $t$
Fase 4 - Test de Transformación de Funciones a través de la red, sin entrenamiento directo (Luciano et al., 2009):

1. Diga las dos reglas y plantee lo que se quiere conseguir al final: "Si el pájaro Tiko canta, sale el sol. Si sale el sol, las flores se abren. Quieres que al final pase esto: «las flores se abren». ¿Qué tiene que pasar primero de todo?" (respuesta: el pájaro Tiko canta).
2. No refuerce diferencialmente durante estos ensayos, pero registre la respuesta. Elegir el suceso intermedio indica que no integra la red.

\1$t$), E'(- Test de vínculo combinatorio:[^\n]*\n)', $t$\1- Transformación de funciones: C → A ("Quieres que al final pase esto: … ¿Qué tiene que pasar primero de todo?"; la respuesta es A)
$t$)
where clinica_id is null and nombre = 'Derivar Relaciones Causales en Redes Combinatorias' and instrucciones_terapeuta not like '%Fase 4 - Test de Transformación de Funciones a través de la red%';
update programas_alumno pa set objetivo = pb.objetivo, secuencia_rft = pb.secuencia_rft, instrucciones_terapeuta = pb.instrucciones_terapeuta
from programas_base pb where pa.programa_base_id = pb.id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones Causales en Redes Combinatorias';

